using UnityEngine;\nusing System;\n\n/// <summary>\nUI component displaying combo count and damage.\n/// </summary>\npublic class ComboCounterUI : MonoBehaviour\n{\n    [SerializeField] private TMPro.TextMeshProUGUI comboText;\n    [SerializeField] private TMPro.TextMeshProUGUI damageText;\n    [SerializeField] private CanvasGroup canvasGroup;\n    [SerializeField] private float fadeOutDelay = 2f;\n    \n    private int currentComboCount = 0;\n    private float totalComboDamage = 0f;\n    private float fadeOutTimer = 0f;\n    \n    private void Start()\n    {\n        CharacterStats.OnComboCountChanged += UpdateComboCount;\n        CombatSystem.OnDamageDealt += AddComboDamage;\n    }\n    \n    private void OnDestroy()\n    {\n        CharacterStats.OnComboCountChanged -= UpdateComboCount;\n        CombatSystem.OnDamageDealt -= AddComboDamage;\n    }\n    \n    private void Update()\n    {\n        if (currentComboCount > 0)\n        {\n            fadeOutTimer += Time.deltaTime;\n            if (fadeOutTimer > fadeOutDelay)\n            {\n                fadeOutTimer = 0f;\n                ResetCombo();\n            }\n        }\n    }\n    \n    private void UpdateComboCount()\n    {\n        // This is called from CharacterStats\n        fadeOutTimer = 0f; // Reset fade timer\n    }\n    \n    private void AddComboDamage(float damage)\n    {\n        totalComboDamage += damage;\n        UpdateDisplay();\n    }\n    \n    private void UpdateDisplay()\n    {\n        if (comboText != null)\n        {\n            string rankText = GetComboRank(currentComboCount);\n            comboText.text = $\"COMBO: {currentComboCount}x\\n{rankText}\";\n        }\n        \n        if (damageText != null)\n        {\n            damageText.text = $\"DMG: {totalComboDamage:F0}\";\n        }\n        \n        if (canvasGroup != null)\n        {\n            canvasGroup.alpha = 1f;\n        }\n    }\n    \n    private string GetComboRank(int comboCount)\n    {\n        return comboCount switch\n        {\n            < 3 => \"Good\",\n            < 6 => \"Great\",\n            < 10 => \"Master\",\n            < 15 => \"Legendary\",\n            _ => \"GODLIKE\"\n        };\n    }\n    \n    private void ResetCombo()\n    {\n        currentComboCount = 0;\n        totalComboDamage = 0f;\n        if (canvasGroup != null)\n        {\n            canvasGroup.alpha = 0f;\n        }\n    }\n}\n"